// The audience's types, as the v1 client typed them (snake_case fields, u64s as numbers): first
// generated by @calimero/abi-codegen from v1's ABI, kept since. The calls are the generated
// [network.calimero.updates.generated.client.UpdatesClient] (`scripts/mobile-codegen.sh` at the repo
// root), which speaks the component ABI; until the logic derives `AbiType` the ABI names these
// types without their shape, so `ComponentWire` converts the client's JSON to and from them.

package network.calimero.updates.generated

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

/** A structured request inside an update. Same three axes as `Post`. */
@Serializable
data class Ask(
    val id: String,
    /** An update's asks are one seek, not a scan of every ask. */
    @SerialName("post_id") val postId: String,
    val content: AskContent,
    @SerialName("edited_at") val editedAt: ULong,
    @SerialName("created_at") val createdAt: ULong,
    val status: String,
    @SerialName("status_at") val statusAt: ULong,
    val deleted: Boolean,
)

@Serializable
data class AskContent(
    val kind: String,
    val title: String,
    val detail: String,
)

@Serializable
data class AskInput(
    /** Set to edit an existing ask of this update; `None` creates one. */
    val id: String? = null,
    val kind: String,
    val title: String,
    val detail: String,
)

@Serializable
data class AskView(
    val id: String,
    @SerialName("post_id") val postId: String,
    @SerialName("post_title") val postTitle: String,
    val kind: String,
    val title: String,
    val detail: String,
    val status: String,
    @SerialName("created_at") val createdAt: ULong,
    @SerialName("offer_count") val offerCount: ULong,
    /**
     * Every offer — for the TEAM only; empty for readers. A presentation
     * filter, not confidentiality (see the module docs).
     */
    val offers: List<OfferView>,
    /** The caller's own offer, if any. */
    @SerialName("my_offer") val myOffer: OfferView? = null,
)

@Serializable
data class Category(
    val id: String,
    val name: String,
    val emoji: String,
    /** A CSS colour token or hex. Presentation only. */
    val color: String,
    @SerialName("created_at") val createdAt: ULong,
    @SerialName("edited_at") val editedAt: ULong,
    val archived: Boolean,
)

@Serializable
data class CategoryView(
    val id: String,
    val name: String,
    val emoji: String,
    val color: String,
    @SerialName("update_count") val updateCount: ULong,
    @SerialName("unread_count") val unreadCount: ULong,
    val muted: Boolean,
)

/**
 * A reply on a post. One level of nesting via `parent_id` ("" for top level).
 *
 * No author field: the author is the entry's owner stamp. Deleting removes the
 * entry — its owner, or a moderator, may.
 */
@Serializable
data class Comment(
    val id: String,
    @SerialName("post_id") val postId: String,
    @SerialName("parent_id") val parentId: String,
    val body: String,
    @SerialName("created_at") val createdAt: ULong,
    @SerialName("edited_at") val editedAt: ULong,
)

@Serializable
data class CommentView(
    val id: String,
    @SerialName("post_id") val postId: String,
    @SerialName("parent_id") val parentId: String,
    val author: String,
    @SerialName("author_name") val authorName: String,
    @SerialName("author_is_team") val authorIsTeam: Boolean,
    val body: String,
    @SerialName("created_at") val createdAt: ULong,
    @SerialName("edited_at") val editedAt: ULong,
)

@Serializable
data class ContributionView(
    @SerialName("ask_id") val askId: String,
    @SerialName("ask_title") val askTitle: String,
    @SerialName("ask_kind") val askKind: String,
    val account: String,
    val name: String,
    val firm: String,
    val note: String,
    @SerialName("accepted_at") val acceptedAt: ULong,
)

@Serializable
data class DraftView(
    val id: String,
    val title: String,
    val payload: String,
    @SerialName("updated_at") val updatedAt: ULong,
)

@Serializable
data class EngagementRow(
    @SerialName("post_id") val postId: String,
    val title: String,
    @SerialName("category_id") val categoryId: String,
    @SerialName("published_at") val publishedAt: ULong,
    val readers: List<ReaderView>,
    /**
     * Non-team members with a profile who have not opened it: the follow-up
     * list.
     */
    @SerialName("not_read") val notRead: List<ReaderView>,
    val reactions: ULong,
    val comments: ULong,
    val offers: ULong,
)

@Serializable
data class Event_AskChanged(
    @SerialName("post_id") val postId: String,
    @SerialName("ask_id") val askId: String,
)

@Serializable
data class Event_CategoryChanged(
    val id: String,
)

@Serializable
data class Event_Commented(
    @SerialName("post_id") val postId: String,
    val id: String,
)

@Serializable
data class Event_OfferChanged(
    @SerialName("post_id") val postId: String,
    @SerialName("ask_id") val askId: String,
)

@Serializable
data class Event_PostDeleted(
    val id: String,
)

@Serializable
data class Event_PostEdited(
    val id: String,
)

@Serializable
data class Event_ProfileSet(
    val account: String,
)

@Serializable
data class Event_QuestionAsked(
    val id: String,
)

@Serializable
data class Event_Reacted(
    @SerialName("post_id") val postId: String,
)

@Serializable
data class Event_Read(
    @SerialName("post_id") val postId: String,
)

@Serializable
data class Event_StatusChanged(
    @SerialName("post_id") val postId: String,
)

@Serializable
data class Event_TeamChanged(
    val account: String,
)

@Serializable
data class Event_UpdatePublished(
    val id: String,
)

@Serializable
data class MeView(
    val account: String,
    val name: String,
    val firm: String,
    @SerialName("is_admin") val isAdmin: Boolean,
    @SerialName("is_team") val isTeam: Boolean,
    val muted: List<String>,
)

@Serializable
data class MeroUpdates(
    /** Admin tier = the signed writer set; `team` grants are verified at merge. */
    val roles: Map<String, Boolean>,
    val settings: Map<String, Settings>,
    val categories: Map<String, Category>,
    /**
     * Flat maps keyed by id, carrying their parent's id — never a nested
     * collection per parent, which would need deterministic re-keying to
     * converge when two nodes create it independently.
     */
    val updates: Map<String, Post>,
    val asks: Map<String, Ask>,
    /** The team's status for a question, keyed by the question's id. */
    @SerialName("question_status") val questionStatus: Map<String, Triage>,
    /** The team's status for an offer, keyed like the offer. */
    @SerialName("offer_status") val offerStatus: Map<String, Triage>,
    val questions: Map<String, Post>,
    val comments: Map<String, Comment>,
    val offers: Map<String, Offer>,
    val reactions: Map<String, Reaction>,
    val reads: Map<String, Read>,
    val profiles: Map<String, Profile>,
    /**
     * Which categories each reader has muted. Its own slot, not a profile
     * field, so renaming yourself on one device and muting on another both
     * survive: a `UserStorage` slot resolves last-writer-wins as a whole.
     */
    val mutes: Map<String, List<String>>,
)

/**
 * One KPI as reported in one update.
 *
 * `value` is a STRING on purpose: founders write "$1.2M", "38%", "12.5k", and
 * the number they meant is the frontend's to parse. The contract keeps what
 * was reported, exactly as reported.
 */
@Serializable
data class Metric(
    val name: String,
    val value: String,
    val unit: String,
)

@Serializable
data class MetricPoint(
    @SerialName("post_id") val postId: String,
    @SerialName("post_title") val postTitle: String,
    val at: ULong,
    val value: String,
)

@Serializable
data class MetricSeries(
    val name: String,
    val unit: String,
    /** Oldest first, one point per update that reported this metric. */
    val points: List<MetricPoint>,
)

/**
 * One reader's offer to help with one ask. Keyed `"<ask_id>|<account>"`, and
 * owned by that account.
 *
 * Two writers, so two records: the HELPER owns this one (`note`/`withdrawn`,
 * by `updated_at`), the TEAM owns its [`Triage`] under the same key. Accepting
 * an offer must not be undone by the helper fixing a typo in their note, and a
 * helper must not be able to accept their own.
 */
@Serializable
data class Offer(
    @SerialName("ask_id") val askId: String,
    val account: String,
    val helper: OfferByHelper,
    @SerialName("updated_at") val updatedAt: ULong,
    @SerialName("created_at") val createdAt: ULong,
)

@Serializable
data class OfferByHelper(
    val note: String,
    val withdrawn: Boolean,
)

@Serializable
data class OfferView(
    @SerialName("ask_id") val askId: String,
    val account: String,
    val name: String,
    val firm: String,
    val note: String,
    val status: String,
    @SerialName("created_at") val createdAt: ULong,
    @SerialName("updated_at") val updatedAt: ULong,
)

@Serializable
data class Overview(
    @SerialName("company_name") val companyName: String,
    @SerialName("cadence_days") val cadenceDays: UInt,
    /** When the latest update went out, 0 if none has. */
    @SerialName("last_update_at") val lastUpdateAt: ULong,
    /** `last_update_at + cadence`, 0 when there is no cadence or no update yet. */
    @SerialName("next_due_at") val nextDueAt: ULong,
    @SerialName("updates_total") val updatesTotal: ULong,
    /** Unread updates in categories the caller has NOT muted. */
    @SerialName("unread_updates") val unreadUpdates: ULong,
    @SerialName("open_asks") val openAsks: ULong,
    @SerialName("open_questions") val openQuestions: ULong,
    val people: ULong,
    @SerialName("is_team") val isTeam: Boolean,
)

@Serializable
data class PersonView(
    val account: String,
    val name: String,
    val firm: String,
    @SerialName("is_admin") val isAdmin: Boolean,
    @SerialName("is_team") val isTeam: Boolean,
    @SerialName("joined_at") val joinedAt: ULong,
    /** Updates this person has opened, out of `updates_total`. */
    @SerialName("updates_read") val updatesRead: ULong,
    @SerialName("updates_total") val updatesTotal: ULong,
    @SerialName("last_read_at") val lastReadAt: ULong,
    val comments: ULong,
    val offers: ULong,
    @SerialName("accepted_offers") val acceptedOffers: ULong,
)

/**
 * An update or a question.
 *
 * Three independent merge axes: CONTENT (the author's edits, by `edited_at`),
 * STATUS (the team's triage of a question, by `status_at`) and the tombstone
 * (OR). Folding status into content would let an author's typo fix silently
 * undo "answered", or the reverse.
 */
@Serializable
data class Post(
    val id: String,
    val kind: String,
    val author: String,
    val content: PostContent,
    @SerialName("edited_at") val editedAt: ULong,
    @SerialName("created_at") val createdAt: ULong,
    val status: String,
    @SerialName("status_at") val statusAt: ULong,
    val deleted: Boolean,
)

@Serializable
data class PostCard(
    val id: String,
    val kind: String,
    val author: String,
    @SerialName("author_name") val authorName: String,
    @SerialName("author_is_team") val authorIsTeam: Boolean,
    val title: String,
    val summary: String,
    @SerialName("category_id") val categoryId: String,
    val status: String,
    @SerialName("created_at") val createdAt: ULong,
    @SerialName("edited_at") val editedAt: ULong,
    @SerialName("comment_count") val commentCount: ULong,
    @SerialName("ask_count") val askCount: ULong,
    @SerialName("open_ask_count") val openAskCount: ULong,
    @SerialName("metric_count") val metricCount: ULong,
    @SerialName("read_count") val readCount: ULong,
    @SerialName("read_by_me") val readByMe: Boolean,
    val reactions: List<ReactionCount>,
)

@Serializable
data class PostContent(
    val title: String,
    val summary: String,
    @SerialName("category_id") val categoryId: String,
    val sections: List<Section>,
    val metrics: List<Metric>,
)

@Serializable
data class PostPage(
    val items: List<PostCard>,
    @SerialName("next_cursor") val nextCursor: String? = null,
)

@Serializable
data class PostView(
    val card: PostCard,
    val sections: List<Section>,
    val metrics: List<Metric>,
    val asks: List<AskView>,
)

/**
 * Who a member says they are. A claim, not an identity: the account id is
 * the only thing that authorises anything.
 */
@Serializable
data class Profile(
    val account: String,
    val name: String,
    /** Fund, firm or company — "Seed Capital", "Angel". */
    val firm: String,
    @SerialName("joined_at") val joinedAt: ULong,
    @SerialName("updated_at") val updatedAt: ULong,
)

/**
 * One account's one emoji on one post. Keyed `"<post_id>|<account>|<emoji>"`,
 * so reacting twice cannot count twice and a second device is the same person.
 */
@Serializable
data class Reaction(
    @SerialName("post_id") val postId: String,
    val account: String,
    val emoji: String,
    val on: Boolean,
    @SerialName("updated_at") val updatedAt: ULong,
)

@Serializable
data class ReactionCount(
    val emoji: String,
    val count: ULong,
    val mine: Boolean,
)

/**
 * A read receipt. Keyed `"<post_id>|<account>"`. Both ends are monotone
 * (first read = min, latest = max), so this merges without any clock
 * tie-break at all.
 */
@Serializable
data class Read(
    @SerialName("post_id") val postId: String,
    val account: String,
    @SerialName("first_at") val firstAt: ULong,
    @SerialName("last_at") val lastAt: ULong,
)

@Serializable
data class ReaderView(
    val account: String,
    val name: String,
    val firm: String,
    @SerialName("first_at") val firstAt: ULong,
)

/** One block of an update: "Highlights", "Lowlights", "Product", "Thanks"… */
@Serializable
data class Section(
    /**
     * A template hint ("highlights", "lowlights", "product", "team", "text"…).
     * Free text so templates can evolve without a contract release.
     */
    val kind: String,
    val title: String,
    val body: String,
)

/** Audience-wide settings, stored under the single key `"main"`. */
@Serializable
data class Settings(
    @SerialName("company_name") val companyName: String,
    /**
     * How often the team means to write, in days. 0 = no cadence. Drives the
     * "next update due" nudge — Visible's recurring-update reminder, without a
     * server to send it.
     */
    @SerialName("cadence_days") val cadenceDays: UInt,
    @SerialName("updated_at") val updatedAt: ULong,
)

/**
 * The team's decision on something a reader wrote: a question's status, an
 * offer's. Kept apart from the reader's record, in team-written storage.
 */
@Serializable
data class Triage(
    val status: String,
    @SerialName("status_at") val statusAt: ULong,
)

@Serializable
data class UpdateInput(
    val title: String,
    val summary: String,
    @SerialName("category_id") val categoryId: String,
    val sections: List<Section>,
    val metrics: List<Metric>,
    val asks: List<AskInput>,
)
